        private async Task FillItemLinks()
        {
            if (menuItems.Count == 0)
            {
                var httpContext = GetHttpContext();
                menuItems = await PortalMenuListLoader.LoadAllAsync(portalMenusClient, httpContext);
            }

            itemLinks.Clear();

            sideBarIcon = "fa-shield";
            if (Key.Equals("Tables"))
            {
                sideBarIcon = "fa-cube";
                itemList = menuItems.Where(i =>
                    {
                        var parent = i.ParentName.AsString().Trim();
                        return parent.EndsWith("Module") && !parent.EndsWith("Queries");
                    })
                    .ToList();
            }
            else if (Key.Equals("Queries"))
            {
                sideBarIcon = "fa-search";
                itemList = menuItems.Where(i => i.ParentName.AsString().Trim().EndsWith("Queries"))
                    .ToList();
            }
            else if (Key.Equals("AuditLogs"))
            {
                sideBarIcon = "fa-shield";
                itemList = menuItems.Where(i =>
                    {
                        var parent = i.ParentName.AsString().Trim();
                        return parent.EndsWith("Module") && !parent.EndsWith("Queries");
                    })
                    .ToList();
            }
            else
            {
                if (Key.EndsWith("Settings"))
                {
                    sideBarIcon = "fa-wrench";
                }

                itemList = menuItems.Where(i => i.ParentName.AsString().Trim().Equals(Key))
                    .ToList();
            }

            foreach (var item in itemList)
            {
                item.Text = item.Text.SplitCamelCaseToString();
                item.Tooltip = item.Text.SplitCamelCaseToString();
            }
        }

