        private static string ToCollapseKey(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "Item";

            var chars = value.Where(char.IsLetterOrDigit).ToArray();
            return chars.Length == 0 ? "Item" : new string(chars);
        }

