        private string GetContentHtml()
        {
            StringBuilder sb = new StringBuilder();
            
            var isCollapsed = false;
            if (Key == "Tables")
            {
                var modules = itemList
                    .Select(i => i.ParentName.AsString().Trim())
                    .Where(p => p.EndsWith("Module") && !p.EndsWith("Queries"))
                    .Distinct();
                foreach (var module in modules)
                {
                    itemList = menuItems.Where(i =>
                            i.ParentName.AsString().Trim().Equals(module) && !i.Name.Equals("AuditLogs"))
                        .ToList();

                    itemLinks.Clear();
                    foreach (var item in itemList)
                    {
                        item.Text = item.Text.SplitCamelCaseToString();
                        item.Tooltip = item.Text.SplitCamelCaseToString();
                    }
                    
                    isCollapsed = false;
                    foreach (var item in itemList.OrderBy(i => i.Text))
                    {
                        if (string.IsNullOrEmpty(item.ActionName))
                            continue;

                        itemLinks.Add(GetItemLink(item.Text, item.ActionName));
                        if (!isCollapsed &&
                            PortalNavigationHelper.IsActivePath(
                                httpContextAccessor.HttpContext!.Request.Path.Value,
                                item.ActionName))
                        {
                            isCollapsed = true;
                        }
                    }

                    var groupHtml = GetGroupHtml();
                    var moduleLabel = module[..^6].SplitCamelCaseToString();
                    sb.AppendLine(GetGroupTriggerHtml(module, isCollapsed, sideBarIcon, moduleLabel));
                    sb.AppendLine(GetCollapseGroupHtml(groupHtml, isCollapsed, module));
                }
            }
            else if (Key == "Queries")
            {
                var queryParents = itemList
                    .Where(i => i.ParentName.AsString().Trim().EndsWith("Queries"))
                    .Select(i => i.ParentName.AsString().Trim())
                    .Distinct()
                    .OrderBy(p => PortalNavigationHelper.FormatSectionTitle(p));
                foreach (var parentName in queryParents)
                {
                    var moduleQueries = menuItems
                        .Where(i => i.ParentName.AsString().Trim().Equals(parentName)
                                    && !string.IsNullOrEmpty(i.ActionName)
                                    && !PortalNavigationHelper.IsAuditLogsQuery(i))
                        .ToList();

                    var tableGroups = moduleQueries
                        .Select(item =>
                        {
                            PortalNavigationHelper.TryGetQueryMenuParts(item, out var tableName, out _);
                            return (Item: item, Table: string.IsNullOrWhiteSpace(tableName) ? "Other" : tableName);
                        })
                        .GroupBy(x => x.Table, StringComparer.OrdinalIgnoreCase)
                        .OrderBy(g => g.Key.SplitCamelCaseToString());

                    isCollapsed = false;
                    itemLinks.Clear();
                    var nestedHtml = new StringBuilder();

                    foreach (var tableGroup in tableGroups)
                    {
                        var tableLabel = tableGroup.Key.SplitCamelCaseToString();
                        var tableCollapseKey = ToCollapseKey($"Q{parentName}_{tableGroup.Key}");
                        var tableExpanded = false;
                        var queryLinks = new StringBuilder();

                        foreach (var entry in tableGroup.OrderBy(x => PortalNavigationHelper.FormatMenuItemTitle(x.Item)))
                        {
                            var linkTitle = PortalNavigationHelper.FormatMenuItemTitle(entry.Item);
                            queryLinks.AppendLine(GetItemLink(linkTitle, entry.Item.ActionName));
                            if (PortalNavigationHelper.IsActivePath(
                                    httpContextAccessor.HttpContext!.Request.Path.Value,
                                    entry.Item.ActionName))
                            {
                                tableExpanded = true;
                                isCollapsed = true;
                            }
                        }

                        if (queryLinks.Length == 0)
                            continue;

                        nestedHtml.AppendLine(GetQueryTableGroupHtml(
                            tableCollapseKey,
                            tableLabel,
                            tableExpanded,
                            queryLinks.ToString()));
                    }

                    if (nestedHtml.Length == 0)
                        continue;

                    var moduleLabel = PortalNavigationHelper.FormatSectionTitle(parentName);
                    var collapseKey = ToCollapseKey(parentName);
                    sb.AppendLine(GetGroupTriggerHtml(collapseKey, isCollapsed, sideBarIcon, moduleLabel));
                    sb.AppendLine(GetCollapseGroupHtml(nestedHtml.ToString(), isCollapsed, collapseKey));
                }
            }
            else if(Key == "AuditLogs")
            {
                var auditLogsItemList = menuItems.Where(i => i.Name.Equals("AuditLogs"))
                    .ToList();
                foreach (var item in auditLogsItemList.OrderBy(i => i.Text))
                {
                    var text = $"{item.ParentName.Replace("Module", "")} {item.Text}";
                    itemLinks.Add(GetItemLink(text.AsSplitCapitalWithUnderline(), item.ActionName));
                    if (!isCollapsed &&
                        PortalNavigationHelper.IsActivePath(
                            httpContextAccessor.HttpContext!.Request.Path.Value,
                            item.ActionName))
                    {
                        isCollapsed = true;
                    }
                }
                
                string groupHtml = GetGroupHtml();
                var auditLabel = Title.SplitCamelCaseToString();
                sb.AppendLine(GetGroupTriggerHtml(Key, isCollapsed, sideBarIcon, auditLabel));
                sb.AppendLine(GetCollapseGroupHtml(groupHtml, isCollapsed));

            }

            else
            {
                foreach (var item in itemList.OrderBy(i => i.Text))
                {
                    itemLinks.Add(GetItemLink(item.Text, item.ActionName));
                    if (!isCollapsed &&
                        PortalNavigationHelper.IsActivePath(
                            httpContextAccessor.HttpContext!.Request.Path.Value,
                            item.ActionName))
                    {
                        isCollapsed = true;
                    }
                }
                
                string groupHtml = GetGroupHtml();
                var groupLabel = Title.SplitCamelCaseToString();
                sb.AppendLine(GetGroupTriggerHtml(Key, isCollapsed, sideBarIcon, groupLabel));
                sb.AppendLine(GetCollapseGroupHtml(groupHtml, isCollapsed));

            }

            return sb.ToString();
        }

        private string BuildSearchText()
        {
            var terms = new List<string>();
            if (!string.IsNullOrWhiteSpace(Title))
            {
                terms.Add(Title.SplitCamelCaseToString());
            }

            if (Key == "AuditLogs")
            {
                foreach (var item in menuItems.Where(i => i.Name.Equals("AuditLogs")))
                {
                    terms.Add($"{item.ParentName.Replace("Module", "")} {item.Text}".AsSplitCapitalWithUnderline());
                }
            }
            else if (Key == "Tables")
            {
                foreach (var module in menuItems
                             .Select(i => i.ParentName.AsString().Trim())
                             .Where(p => p.EndsWith("Module") && !p.EndsWith("Queries"))
                             .Distinct())
                {
                    terms.Add(module[..^6].SplitCamelCaseToString());
                    foreach (var page in menuItems.Where(i =>
                                 i.ParentName.AsString().Trim().Equals(module) &&
                                 !i.Name.Equals("AuditLogs")))
                    {
                        if (!string.IsNullOrWhiteSpace(page.Text))
                        {
                            terms.Add(page.Text.SplitCamelCaseToString());
                        }
                    }
                }
            }
            else if (Key == "Queries")
            {
                foreach (var parentName in menuItems
                             .Where(i => i.ParentName.AsString().Trim().EndsWith("Queries"))
                             .Select(i => i.ParentName.AsString().Trim())
                             .Distinct())
                {
                    terms.Add(PortalNavigationHelper.FormatSectionTitle(parentName));
                    foreach (var page in menuItems.Where(i =>
                                 i.ParentName.AsString().Trim().Equals(parentName)
                                 && !PortalNavigationHelper.IsAuditLogsQuery(i)))
                    {
                        if (PortalNavigationHelper.TryGetQueryMenuParts(page, out var tableName, out var filterName))
                        {
                            if (!string.IsNullOrWhiteSpace(tableName))
                                terms.Add(tableName.SplitCamelCaseToString());
                            if (!string.IsNullOrWhiteSpace(filterName))
                                terms.Add(filterName.SplitCamelCaseToString());
                        }
                        else if (!string.IsNullOrWhiteSpace(page.Text))
                        {
                            terms.Add(page.Text.SplitCamelCaseToString());
                        }
                    }
                }
            }
            else
            {
                foreach (var item in itemList)
                {
                    if (!string.IsNullOrWhiteSpace(item.Text))
                    {
                        terms.Add(item.Text);
                    }
                }
            }

            return string.Join(' ', terms)
                .ToLowerInvariant()
                .Trim();
        }
